 * Standalone driver: read a file from argv[1] and feed it to the xml fuzzer.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <libxml/parser.h>
#include "fuzz.h"

int LLVMFuzzerInitialize(int *argc, char ***argv);
int LLVMFuzzerTestOneInput(const char *data, size_t size);

int main(int argc, char **argv) {
    FILE *f;
    char *data;
    long size;

    if (argc < 2) {
        fprintf(stderr, "usage: %s <input>\n", argv[0]);
        return 2;
    }

    LLVMFuzzerInitialize(&argc, &argv);

    f = fopen(argv[1], "rb");
    if (f == NULL) {
        perror("fopen");
        return 2;
    }
    fseek(f, 0, SEEK_END);
    size = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (size < 0) {
        fclose(f);
        return 2;
    }
    data = malloc(size > 0 ? size : 1);
    if (data == NULL) {
        fclose(f);
        return 2;
    }
    if (size > 0 && fread(data, 1, size, f) != (size_t)size) {
        fclose(f);
        free(data);
        return 2;
    }
    fclose(f);

    LLVMFuzzerTestOneInput(data, size);

    free(data);
    xmlCleanupParser();
    return 0;
}
"}

